begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
 ('aaaa6000-0000-4000-8000-000000000001','config-organizer@test.invalid','{"display_name":"Config Organizer"}'),
 ('aaaa6000-0000-4000-8000-000000000002','config-judge@test.invalid','{"display_name":"Config Judge"}'),
 ('aaaa6000-0000-4000-8000-000000000003','config-trainer@test.invalid','{"display_name":"Config Trainer"}'),
 ('aaaa6000-0000-4000-8000-000000000004','config-line@test.invalid','{"display_name":"Config Line"}');
insert into public.staff_accounts(id,email,display_name) select id,email,'Config Fixture' from auth.users where id::text like 'aaaa6000-%';
insert into public.staff_roles values('aaaa6000-0000-4000-8000-000000000001','organizer'),('aaaa6000-0000-4000-8000-000000000002','main_judge'),('aaaa6000-0000-4000-8000-000000000003','trainer'),('aaaa6000-0000-4000-8000-000000000004','line_judge');
create temp table format_fixture(definition jsonb);
insert into format_fixture values('{"nodes":[{"ordinal":1,"kind":"round_robin","group_count":4,"group_size":6},{"ordinal":2,"kind":"knockout","size":8,"source_ordinal":1,"place_from":1,"place_to":2},{"ordinal":3,"kind":"knockout","size":8,"source_ordinal":1,"place_from":3,"place_to":4},{"ordinal":4,"kind":"knockout","size":8,"source_ordinal":1,"place_from":5,"place_to":6}]}');
grant select on format_fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"aaaa6000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.save_season('bbbb6000-0000-4000-8000-000000000001','Config Season',2026,'2026-01-01','2026-12-31');
select is(public.season_configuration_readiness('bbbb6000-0000-4000-8000-000000000001')->'problems','["no_tours"]'::jsonb,'empty season requires tour');
select public.save_tour('cccc6000-0000-4000-8000-000000000001','bbbb6000-0000-4000-8000-000000000001','Config Tour',1,'2026-03-01','2026-03-03');
select is(public.season_configuration_readiness('bbbb6000-0000-4000-8000-000000000001')->'problems','["missing_settings","missing_stage_plans"]'::jsonb,'missing settings and all age plans identified');
select lives_ok($$select public.create_stage_template('dddd6000-0000-4000-8000-000000000001','Four groups three brackets',(select definition from format_fixture))$$,'create confirmed composite format');
select is((select entry_count from public.stage_templates where id='dddd6000-0000-4000-8000-000000000001'),24,'confirmed format consumes 24 clubs');
select lives_ok($$select public.create_stage_template('dddd6000-0000-4000-8000-000000000001','Four groups three brackets',(select definition from format_fixture))$$,'template exact retry is idempotent');
select throws_ok($$select public.create_stage_template('dddd6000-0000-4000-8000-000000000001','Changed name',(select definition from format_fixture))$$,'22023','Template ID conflict','template cannot overwrite immutable ID');
select throws_ok($$select public.create_stage_template(gen_random_uuid(),'Overlap',jsonb_set((select definition from format_fixture),'{nodes,2,place_from}','2'))$$,'22023','Invalid stage template','malformed partition size rejected');
select throws_ok($$select public.create_stage_template(gen_random_uuid(),'Overlap',jsonb_set(jsonb_set((select definition from format_fixture),'{nodes,2,place_from}','1'),'{nodes,2,place_to}','2'))$$,'22023','Overlapping placement bands','overlapping bands rejected independently');
select throws_ok($$select public.create_stage_template(gen_random_uuid(),'Missing band',jsonb_set((select definition from format_fixture),'{nodes}',((select definition->'nodes' from format_fixture)-3)))$$,'22023','Incomplete placement bands','every source place must route exactly once');
select throws_ok($$select public.create_stage_template(gen_random_uuid(),'Wrong ordinal',jsonb_set((select definition from format_fixture),'{nodes,0,ordinal}','null'))$$,'22023','Invalid stage template','null root ordinal rejected');
select throws_ok($$select public.create_stage_template(gen_random_uuid(),'Cycle',jsonb_set((select definition from format_fixture),'{nodes,1,source_ordinal}','2'))$$,'22023','Invalid stage template','self/cyclic routing rejected');
select throws_ok($$select public.create_stage_template(gen_random_uuid(),'Non power', '{"nodes":[{"ordinal":1,"kind":"knockout","size":6}]}')$$,'22023','Invalid stage template','knockout size must be power of two');
select lives_ok($$select public.create_stage_template('dddd6000-0000-4000-8000-000000000002','Round robin only','{"nodes":[{"ordinal":1,"kind":"round_robin","group_count":4,"group_size":6}]}')$$,'atomic round-robin supported');
select lives_ok($$select public.create_stage_template('dddd6000-0000-4000-8000-000000000003','Knockout only','{"nodes":[{"ordinal":1,"kind":"knockout","size":8}]}')$$,'atomic knockout supported');
select lives_ok($$select public.save_tournament_settings('eeee6000-0000-4000-8000-000000000001','cccc6000-0000-4000-8000-000000000001',0,32,12,60,true,'Asia/Almaty')$$,'organizer configures explicit K and confirmed hall settings');
select throws_ok($$select public.save_tournament_settings(gen_random_uuid(),'cccc6000-0000-4000-8000-000000000001',0,64,12,60,true,'Asia/Almaty')$$,'22023','Settings revision conflict','stale settings revision cannot overwrite');
select lives_ok($$select public.save_tournament_settings('eeee6000-0000-4000-8000-000000000001','cccc6000-0000-4000-8000-000000000001',0,32,12,60,true,'Asia/Almaty')$$,'settings exact retry returns original version');
select throws_ok($$select public.save_tournament_settings(gen_random_uuid(),'cccc6000-0000-4000-8000-000000000001',1,0,12,60,true,'Asia/Almaty')$$,'22023','Invalid tournament settings','zero K rejected');
select throws_ok($$select public.save_tournament_settings(gen_random_uuid(),'cccc6000-0000-4000-8000-000000000001',1,'NaN',12,60,true,'Asia/Almaty')$$,'22023','Invalid tournament settings','NaN K rejected');
select throws_ok($$select public.save_tournament_settings(gen_random_uuid(),'cccc6000-0000-4000-8000-000000000001',1,'Infinity',12,60,true,'Asia/Almaty')$$,'22023','Invalid tournament settings','infinite K rejected');
select throws_ok($$select public.save_tournament_settings(gen_random_uuid(),'cccc6000-0000-4000-8000-000000000001',1,32,0,60,true,'Asia/Almaty')$$,'22023','Invalid tournament settings','zero tables rejected');
select throws_ok($$select public.save_tournament_settings(gen_random_uuid(),'cccc6000-0000-4000-8000-000000000001',1,32,12,-1,true,'Asia/Almaty')$$,'22023','Invalid tournament settings','negative rest rejected');
select throws_ok($$select public.save_tournament_settings(gen_random_uuid(),'cccc6000-0000-4000-8000-000000000001',1,32,12,60,true,'Invented/Timezone')$$,'22023','Invalid tournament settings','invalid timezone rejected in database');
select lives_ok($$select public.configure_tour_stages('cccc6000-0000-4000-8000-000000000001','dddd6000-0000-4000-8000-000000000001',array['U13']::public.age_group[])$$,'configure one age group');
select ok(public.season_configuration_readiness('bbbb6000-0000-4000-8000-000000000001')->'problems' ? 'missing_stage_plans','partial age coverage not ready');
select lives_ok($$select public.configure_tour_stages('cccc6000-0000-4000-8000-000000000001','dddd6000-0000-4000-8000-000000000001',array['U13','U15','U17']::public.age_group[])$$,'apply same reusable template to all three ages');
select is((select count(*)::int from public.tour_stage_plans where tour_id='cccc6000-0000-4000-8000-000000000001'),3,'same plan retry does not duplicate revisions');
select is((select count(*)::int from public.stages where plan_id in(select id from public.tour_stage_plans where tour_id='cccc6000-0000-4000-8000-000000000001')),12,'three age groups have four individual stage rows each');
select is(public.season_configuration_readiness('bbbb6000-0000-4000-8000-000000000001')->'problems','["entry_count_mismatch"]'::jsonb,'configuration alone cannot start without registered clubs');
select throws_ok($$select public.start_season('bbbb6000-0000-4000-8000-000000000001')$$,'22023','Stage and settings readiness required','start rechecks readiness in SQL');
select throws_ok($$select public.configure_tour_stages('cccc6000-0000-4000-8000-000000000001','dddd6000-0000-4000-8000-000000000001',array['U13','U13']::public.age_group[])$$,'22023','Template and age groups required','duplicate ages rejected');
select lives_ok($$select public.configure_tour_stages('cccc6000-0000-4000-8000-000000000001','dddd6000-0000-4000-8000-000000000002',array['U13']::public.age_group[])$$,'draft plan can be replaced');
select lives_ok($$select public.configure_tour_stages('cccc6000-0000-4000-8000-000000000001','dddd6000-0000-4000-8000-000000000001',array['U13']::public.age_group[])$$,'draft plan can return to previous template as new revision');
select is((select count(*)::int from public.tour_stage_plans where tour_id='cccc6000-0000-4000-8000-000000000001' and age_group='U13'),3,'prior plans retained');
select lives_ok($$do $inner$ declare i integer; club uuid; begin for i in 1..24 loop club:=gen_random_uuid(); perform public.save_team(club,'Config Club '||i,'Synthetic'); perform public.register_season_team('bbbb6000-0000-4000-8000-000000000001',club); end loop; end;$inner$;$$,'register 24 clubs through authenticated business RPCs');
select is(public.season_configuration_readiness('bbbb6000-0000-4000-8000-000000000001')->>'ready','true','24 registered clubs and complete configuration are ready without roster-gender preconditions');
select lives_ok($$select public.start_season('bbbb6000-0000-4000-8000-000000000001')$$,'start ready season');
select lives_ok($$select public.start_season('bbbb6000-0000-4000-8000-000000000001')$$,'start retry idempotent');
select is((select count(*)::int from public.season_configuration_snapshots where season_id='bbbb6000-0000-4000-8000-000000000001'),1,'exactly one immutable season snapshot');
select is((select configuration#>>'{tours,0,settings_id}' from public.season_configuration_snapshots where season_id='bbbb6000-0000-4000-8000-000000000001'),'eeee6000-0000-4000-8000-000000000001','start snapshot pins settings ID');
select is((select jsonb_array_length(configuration#>'{tours,0,plan_ids}') from public.season_configuration_snapshots where season_id='bbbb6000-0000-4000-8000-000000000001'),3,'start pins exactly three current stage plans');
select throws_ok($$select public.configure_tour_stages('cccc6000-0000-4000-8000-000000000001','dddd6000-0000-4000-8000-000000000002',array['U13']::public.age_group[])$$,'22023','Season configuration locked','started stages locked');
select throws_ok($$select public.save_tournament_settings(gen_random_uuid(),'cccc6000-0000-4000-8000-000000000001',1,64,13,60,true,'Asia/Almaty')$$,'22023','Season configuration locked','started table count locked');
select throws_ok($$select public.save_tournament_settings(gen_random_uuid(),'cccc6000-0000-4000-8000-000000000001',1,64,12,0,true,'Asia/Almaty')$$,'22023','Season configuration locked','started rest locked');
select throws_ok($$select public.save_tournament_settings(gen_random_uuid(),'cccc6000-0000-4000-8000-000000000001',1,64,12,60,false,'Asia/Almaty')$$,'22023','Season configuration locked','started finals policy locked');
select throws_ok($$select public.save_tournament_settings(gen_random_uuid(),'cccc6000-0000-4000-8000-000000000001',1,64,12,60,true,'UTC')$$,'22023','Season configuration locked','started venue timezone locked');
select lives_ok($$select public.save_tournament_settings('eeee6000-0000-4000-8000-000000000002','cccc6000-0000-4000-8000-000000000001',1,64,12,60,true,'Asia/Almaty')$$,'K exception appends new prospective version after season start');
select is((select k_factor::int from public.tournament_settings where id='eeee6000-0000-4000-8000-000000000001'),32,'original K version preserved');
select is((select configuration#>>'{tours,0,settings_id}' from public.season_configuration_snapshots where season_id='bbbb6000-0000-4000-8000-000000000001'),'eeee6000-0000-4000-8000-000000000001','prospective K cannot rewrite start snapshot');
select is((select count(*)::int from public.audit_logs where action='season.started' and entity_id='bbbb6000-0000-4000-8000-000000000001'),1,'start audited once');
select is((select before_state->>'k_factor' from public.audit_logs where action='tournament_settings.created' and entity_id='cccc6000-0000-4000-8000-000000000001' and after_state->>'revision'='2'),'32','K change audit retains prior value');
select throws_ok($$update public.tournament_settings set k_factor=1$$,'42501',null,'direct settings overwrite denied');
select throws_ok($$delete from public.stage_templates$$,'42501',null,'direct template deletion denied');
select throws_ok($$update public.stages set ordinal=99$$,'42501',null,'direct stage overwrite denied');
select throws_ok($$delete from public.season_configuration_snapshots$$,'42501',null,'direct snapshot deletion denied');
select set_config('request.jwt.claims','{"sub":"aaaa6000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.save_tournament_settings(gen_random_uuid(),'cccc6000-0000-4000-8000-000000000001',2,64,12,60,true,'Asia/Almaty')$$,'42501','Organizer required','main judge cannot change K/settings');
select throws_ok($$select public.create_stage_template(gen_random_uuid(),'Judge template','{"nodes":[{"ordinal":1,"kind":"knockout","size":8}]}')$$,'42501','Organizer required','main judge cannot create template');
select throws_ok($$select public.configure_tour_stages('cccc6000-0000-4000-8000-000000000001','dddd6000-0000-4000-8000-000000000001',array['U13']::public.age_group[])$$,'42501','Organizer required','main judge cannot change stages');
select set_config('request.jwt.claims','{"sub":"aaaa6000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.season_configuration_readiness('bbbb6000-0000-4000-8000-000000000001')$$,'42501','Organizer required','trainer cannot invoke Organizer readiness command');
select set_config('request.jwt.claims','{"sub":"aaaa6000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select throws_ok($$select public.start_season('bbbb6000-0000-4000-8000-000000000001')$$,'42501','Organizer required','line judge cannot start season');
reset role;
update public.staff_accounts set active=false where id='aaaa6000-0000-4000-8000-000000000004';
set local role authenticated;
select is((select count(*)::int from public.tournament_settings),0,'inactive staff cannot read settings');
set local role anon;
select throws_ok($$select * from public.tournament_settings$$,'42501',null,'anonymous private settings denied');
select throws_ok($$select * from public.stage_templates$$,'42501',null,'anonymous template reads denied');
select throws_ok($$select public.season_configuration_readiness('bbbb6000-0000-4000-8000-000000000001')$$,'42501',null,'anonymous readiness RPC denied');
select * from finish();
rollback;
